import puppeteer from 'puppeteer-core';
const baseUrl=process.env.TEST_URL,executablePath=process.env.CHROME_PATH;if(!baseUrl||!executablePath)throw new Error('TEST_URL/CHROME_PATH missing');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const browser=await puppeteer.launch({executablePath,headless:true,args:['--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--no-first-run','--no-default-browser-check'],timeout:30000});
async function waitFor(fn,timeout=20000,step=100){const end=Date.now()+timeout;while(Date.now()<end){try{if(await fn())return true}catch(e){}await sleep(step)}return false}
async function makeClient(label,score=0){const context=await browser.createBrowserContext(),page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(String(e?.stack||e?.message||e)));page.on('console',m=>{if(m.type()==='error'&&!/Failed to load resource:.*404/i.test(m.text()))errors.push('console: '+m.text())});await page.evaluateOnNewDocument(({label,score})=>{try{localStorage.setItem('BombermanPlayerName',label);localStorage.setItem('BombermanRatingV1',String(score));localStorage.setItem('BombermanScoreV1Initialized','1');localStorage.setItem('BombermanMultiplayerAIEnabled','1');localStorage.setItem('BombermanAIDifficultyV1','normal');localStorage.removeItem('BombermanPlayerWinsV1');localStorage.removeItem('BombermanPlayerLossesV1')}catch(e){}try{if(navigator.serviceWorker)navigator.serviceWorker.register=()=>Promise.resolve({scope:location.href})}catch(e){}},{label,score});await page.goto(baseUrl,{waitUntil:'domcontentloaded',timeout:20000});await page.waitForFunction(()=>window.BomberV127&&BomberV127.version==='v0.12.7'&&window.BomberLeaderboard127&&window.BomberV124&&window.BomberV125&&window.BomberDataSync&&gGameEngine?.menu&&document.getElementById('mainSettingsTile')&&document.getElementById('mainLeaderboardTile'),{timeout:20000});return{context,page,errors,label}}
async function snap(page){return page.evaluate(()=>({role:B115.role,started:B115.started,score:BomberV127.getScore(),wins:BomberLeaderboard127.wins(),losses:BomberLeaderboard127.losses(),round:BomberV127.round(),players:gGameEngine.players.map(p=>({alive:p.alive})),bots:gGameEngine.bots.map(b=>({alive:b.alive,sim:!!b.simulatedHuman})),elim:!!document.getElementById('qolEliminated')&&!document.getElementById('qolEliminated').hidden,rematchNow:!!document.getElementById('v127RematchNow')&&!document.getElementById('v127RematchNow').hidden&&getComputedStyle(document.getElementById('v127RematchNow')).display!=='none',prompt:!!document.getElementById('qolRematchPrompt')&&!document.getElementById('qolRematchPrompt').hidden,post:!!document.getElementById('qolPostMatch')&&!document.getElementById('qolPostMatch').hidden,version:document.getElementById('buildVersion127')?.textContent}))}
async function connect(A,B,id){await A.page.evaluate(id=>{BomberV124.setAIEnabled(true);BomberV125.setDifficulty('normal');B115.privateId=()=>id;B115.els.privateCode.value='9';B115.els.name.value='Host127';B115.startPrivateHost()},id);await sleep(800);await B.page.evaluate(id=>{B115.privateId=()=>id;B115.els.privateCode.value='9';B115.els.name.value='Guest127';B115.startPrivateJoin()},id);const ok=await waitFor(async()=>{const[a,b]=await Promise.all([snap(A.page),snap(B.page)]);return a.started&&b.started&&a.role==='host'&&b.role==='guest'&&a.players.length===2&&b.players.length===2},25000,150);if(!ok)throw new Error('v127 pair did not connect');await sleep(900)}
async function close(c){await c?.context.close().catch(()=>{})}
