 console.log('MAIN_UI',JSON.stringify({version:main.version,settings:main.settings,leaderboard:main.leaderboard,customName:main.customName,topCount:main.top.length}));if(!mainReady||main.version!=='v0.12.7'||main.settings==='none'||main.leaderboard==='none'||main.customName!=='Cole127'||main.top.length!==50)throw new Error('v0.12.7 menu/leaderboard/stable name did not initialize');
 const samples=[];for(let i=0;i<8;i++){samples.push(await C.page.$eval('#mainCustomizeTile .customize_name',e=>e.textContent));await sleep(90)}if(samples.some(x=>x!=='Cole127'))throw new Error('customize name still flickers: '+JSON.stringify(samples));
 await C.page.click('#mainSettingsTile');await sleep(120);let settings=await C.page.evaluate(()=>({hidden:document.getElementById('v127SettingsPanel').hidden,buttons:[...document.querySelectorAll('[data-v127-diff]')].map(b=>b.textContent),headings:[...document.querySelectorAll('#v127SettingsPanel .v127_section h3')].map(h=>h.textContent)}));if(settings.hidden||settings.buttons.join(',')!=='Easy,Normal,Hard,Expert'||settings.headings.some(x=>/matchmaking log|search activity/i.test(x)))throw new Error('settings panel did not keep AI difficulty cleanly without matchmaking/search log');
 await C.page.click('[data-v127-diff="hard"]');await sleep(80);let diff=await C.page.evaluate(()=>({runtime:BomberV125.getDifficulty(),stored:localStorage.getItem('BombermanAIDifficultyV1')}));if(diff.runtime!=='hard'||diff.stored!=='hard')throw new Error('single-player AI difficulty did not persist');await C.page.click('#v127SettingsPanel .v127_close');await sleep(80);
 await C.page.click('#mainLeaderboardTile');await sleep(80);let lb=await C.page.evaluate(()=>({hidden:document.getElementById('v127LeaderboardPanel').hidden,rows:document.querySelectorAll('#v127LbList .v127_lb_row').length,you:document.getElementById('v127LbYou').textContent,first:BomberLeaderboard127.top50()[0],last:BomberLeaderboard127.top50()[49]}));if(lb.hidden||lb.rows!==50||!/Cole127/.test(lb.you)||!/0/.test(lb.you)||!(lb.first.score>=lb.last.score))throw new Error('leaderboard did not render 50 deterministic fake profiles plus player row');await C.page.click('#v127LeaderboardPanel .v127_lb_close');
