 let[a,b]=await Promise.all([snap(A.page),snap(B.page)]);if(a.score!==110||b.score!==190||a.wins!==1||b.losses!==1)throw new Error('rematch altered settled scores/WL');console.log('SECOND_DEATH_REMATCH PASS');
 await A.page.evaluate(()=>gGameEngine.players[1].die());await waitFor(async()=>{const[a,b]=await Promise.all([snap(A.page),snap(B.page)]);return a.score===120&&b.score===180&&a.wins===2&&b.losses===2&&a.round.duelResolved},6000,100);
 await A.page.evaluate(()=>{gGameEngine.bots.filter(b=>!b.simulatedHuman).slice().forEach(b=>b.die())});
 const bonus=await waitFor(async()=>{const s=await snap(A.page);return s.score===125&&s.wins===2&&s.losses===0&&s.round.aiBonusResolved},6000,100);if(!bonus){const s=await snap(A.page);throw new Error('AI clear did not award exactly +5 without changing WL: '+JSON.stringify(s))}
